51	/** Revokes (deletes) a share link. */
52	export function useDeleteMemoShare() {
53	  const queryClient = useQueryClient();
54	  return useMutation({
55	    mutationFn: async ({ name, memoName }: { name: string; memoName: string }) => {
56	      await memoServiceClient.deleteMemoShare(create(DeleteMemoShareRequestSchema, { name }));
57	      return memoName;
58	    },
59	    onSuccess: (_data, variables) => {
60	      queryClient.invalidateQueries({ queryKey: memoShareKeys.list(variables.memoName) });
61	    },
